-- Report It (Pharmacovigilance) — report_it_reports table
--
-- Stores employee adverse-drug-reaction reports submitted via the
-- VigiFlow-inspired "Report It" employee module.
--
-- DESIGN:
--   * submitted_by_hr_id is a TEXT FK to employees(hr_id) — matching the
--     existing Phoenix pattern (HR_ID is the employee key, not a DB uuid).
--   * report_number is generated by a DB function (RPT-YYYY-NNNNN) via an
--     auto-incrementing sequence; it is UNIQUE and pre-set on INSERT.
--   * report_payload stores the full structured form data as JSONB so the
--     schema can evolve without migration cost.
--   * RLS is ENABLED on both tables but the app-layer uses the service-role
--     client (bypasses RLS) for writes, and enforces per-user filtering in
--     application code (employees can only read their own rows).
--   * An updated_at trigger keeps the timestamp fresh on every UPDATE.
--
-- SAFETY: all statements are idempotent (IF NOT EXISTS / OR REPLACE).

begin;

-- ─────────────────────────────────────────────────────────────
-- 1. Sequence for report number generation
-- ─────────────────────────────────────────────────────────────
create sequence if not exists report_it_report_number_seq
  start 1
  increment 1
  no cycle;

-- ─────────────────────────────────────────────────────────────
-- 2. Helper function: generate RPT-YYYY-NNNNN
-- ─────────────────────────────────────────────────────────────
create or replace function generate_report_it_number()
returns text
language plpgsql
as $$
declare
  year_str text;
  seq_num  bigint;
begin
  year_str := to_char(now(), 'YYYY');
  seq_num  := nextval('report_it_report_number_seq');
  return 'RPT-' || year_str || '-' || lpad(seq_num::text, 5, '0');
end;
$$;

-- ─────────────────────────────────────────────────────────────
-- 3. Main reports table
-- ─────────────────────────────────────────────────────────────
create table if not exists report_it_reports (
  id                   uuid        primary key default gen_random_uuid(),
  report_number        text        unique not null default generate_report_it_number(),

  -- Submitter info (denormalised for dashboard display and export)
  submitted_by_hr_id   text        references employees(hr_id) on delete set null,
  submitted_by_name    text,
  submitted_by_role    text,
  department           text,
  line                 text,
  area                 text,

  -- Searchable patient fields
  patient_initials     text,
  patient_sex          text,
  patient_country      text        not null default 'Egypt',

  -- Searchable reaction summary fields
  is_serious           boolean     not null default false,
  outcome_summary      text,
  suspected_medicines  text[]      not null default '{}',
  reactions_summary    text[]      not null default '{}',

  -- Full structured payload
  report_payload       jsonb       not null default '{}',

  -- Lifecycle
  status               text        not null default 'submitted',
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

-- ─────────────────────────────────────────────────────────────
-- 4. Audit log table
-- ─────────────────────────────────────────────────────────────
create table if not exists report_it_audit_logs (
  id          uuid        primary key default gen_random_uuid(),
  report_id   uuid        references report_it_reports(id) on delete cascade,
  actor_hr_id text,
  action      text        not null,
  metadata    jsonb       not null default '{}',
  created_at  timestamptz not null default now()
);

-- ─────────────────────────────────────────────────────────────
-- 5. Indexes
-- ─────────────────────────────────────────────────────────────
create index if not exists idx_report_it_submitted_by
  on report_it_reports(submitted_by_hr_id);

create index if not exists idx_report_it_created_at
  on report_it_reports(created_at desc);

create index if not exists idx_report_it_is_serious
  on report_it_reports(is_serious);

create index if not exists idx_report_it_status
  on report_it_reports(status);

create index if not exists idx_report_it_audit_report
  on report_it_audit_logs(report_id);

-- ─────────────────────────────────────────────────────────────
-- 6. Updated-at trigger
-- ─────────────────────────────────────────────────────────────
create or replace function report_it_set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists report_it_reports_updated_at on report_it_reports;
create trigger report_it_reports_updated_at
  before update on report_it_reports
  for each row execute function report_it_set_updated_at();

-- ─────────────────────────────────────────────────────────────
-- 7. RLS — enabled; app-layer uses service-role for writes and
--    enforces per-user row filtering in application code.
-- ─────────────────────────────────────────────────────────────
alter table report_it_reports    enable row level security;
alter table report_it_audit_logs enable row level security;

-- Ask PostgREST to refresh its schema cache.
notify pgrst, 'reload schema';

commit;
